function Config.PartnerHolyEqmData.data_const_fun(slot0)
	slot1 = Config.PartnerHolyEqmData.data_const[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.PartnerHolyEqmData.data_const[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

