Config.PartnerHolyEqmData.data_base_info_length = 1680
Config.PartnerHolyEqmData.data_base_info_cache = {}

function Config.PartnerHolyEqmData.data_base_info(slot0)
	if Config.PartnerHolyEqmData.data_base_info_cache[slot0] == nil then
		if not Config.PartnerHolyEqmData.data_base_info_table[slot0] then
			return
		end

		if not loadstring(string.format("return %s", slot1))() then
			return
		end

		Config.PartnerHolyEqmData.data_base_info_cache[slot0] = {
			id = slot1[1],
			attr_num = slot1[2],
			group_id = slot1[3],
			limit = slot1[4],
			reset_price = slot1[5],
			unlock_desc = slot1[6],
			is_show = slot1[7],
			sort = slot1[8],
			tips_info = slot1[9],
			show_name = slot1[10],
			score = slot1[11]
		}
	end

	return Config.PartnerHolyEqmData.data_base_info_cache[slot0]
end

